/bin/bash -lc "python3 - <<'PY'
import subprocess
import tempfile
from pathlib import Path
source = r'''
#include \"service.hpp\"
#include <cassert>
int main() {
    for (int port = 1; port <= 65535; ++port) {
        assert(parsePort(std::to_string(port)) == port);
        assert(parsePort(\"000\" + std::to_string(port)) == port);
    }
    for (const auto& s : {std::string(\"\"), std::string(\"0\"), std::string(\"000\"),
                         std::string(\"65536\"), std::string(\"99999\"),
                         std::string(\"2147483647\"), std::string(\"2147483648\"),
                         std::string(10000, '9'), std::string(\"+1\"),
                         std::string(\"-1\"), std::string(\" 1\"), std::string(\"1 \"),
                         std::string(\"1\\n\"), std::string(\"1.0\"), std::string(\"1x\"),
                         std::string(\"1\\0\", 2), std::string(\"\\xFF\"),
                         std::string(\"\\xD9\\xA1\")}) {
        assert(parsePort(s) == -1);
    }
    assert(parsePort(std::string(10000, '0') + \"65535\") == 65535);
    for (int byte = 0; byte < 256; ++byte) {
        std::string s(1, static_cast<char>(byte));
        int expected = byte >= '1' && byte <= '9' ? byte - '0' : -1;
        assert(parsePort(s) == expected);
    }
}
'''
with tempfile.TemporaryDirectory(prefix='parse-port-check-') as directory:
    binary = str(Path(directory) / 'check')
    subprocess.run(['c++', '-std=c++17', '-Wall', '-Wextra', '-Werror', '-fsanitize=undefined', '-I', '.', '-x', 'c++', '-o', binary, '-'], input=source, text=True, check=True)
    subprocess.run([binary], check=True)
print('Extended port checks passed with undefined-behavior sanitizer.')
PY"

